"""Independent RFC Privacy Pass fixtures and actual public-token verification cases."""

from ..privacy_pass import Token, rfc_fixtures, verify_public_token
from . import File


def generate() -> list[File]:
    fixtures = rfc_fixtures()
    f = File(
        "storage",
        "privacy-pass-rfc9578",
        "Source: " + fixtures["source"] + "; SHA-256 " + fixtures["source_sha256"] + ". "
        "RFC fixture issuance fields are upstream known answers, not outputs generated by Hum. "
        "Type-1 cases check framing only; no OPRF verification is claimed. Type-2 cases also "
        "execute cryptography's RSA-PSS verification against the exact challenge and key. "
        "Blind issuance, context token-key binding and atomic spent-nonce redemption remain separate checks.",
    )
    for c in fixtures["cases"]:
        raw, challenge, key = (bytes.fromhex(c[n]) for n in ("token", "token_challenge", "pkI"))
        token = Token.decode(raw)
        expected = {
            "type": token.token_type,
            "nonce": token.nonce.hex(),
            "challenge_digest": token.challenge_digest.hex(),
            "key_id": token.key_id.hex(),
        }
        if token.token_type == 2:
            assert verify_public_token(raw, challenge, key)
            expected["signature_verified"] = True
        f.add(
            f"rfc-{c['id']}",
            "RFC 9578 token framing"
            + (
                " and RSA-PSS verification"
                if token.token_type == 2
                else " (OPRF authentication pending)"
            ),
            "RFC 9578 Appendix A/B",
            c,
            expected,
        )
        if token.token_type == 2:
            for suffix, altered, ctx in (
                ("signature", raw[:-1] + bytes([raw[-1] ^ 1]), challenge),
                ("challenge", raw, challenge + b"x"),
            ):
                assert not verify_public_token(altered, ctx, key)
                f.add(
                    f"rfc-{c['id']}-wrong-{suffix}",
                    "Refuse altered " + suffix,
                    "RFC 9578 §6.4",
                    {"token": altered.hex(), "challenge": ctx.hex(), "issuer_key": key.hex()},
                    rejection={"step": None, "check": "public-token-verification"},
                )
    return [f]
